--
-- Name: archive_learner_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_learner_profile(p_learner_profile_id uuid) RETURNS public.learner_profile
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_owner_account_id uuid;
  v_profile public.learner_profile%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  select account.id
  into v_owner_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  join public.course_learner as course_learner
    on course_learner.course_id = course.id
  where course_learner.learner_profile_id = p_learner_profile_id
    and course.owner_account_id = v_owner_account_id
  order by course.id
  for update of course;

  select profile.*
  into v_profile
  from public.learner_profile as profile
  where profile.id = p_learner_profile_id
    and profile.owner_account_id = v_owner_account_id
  for update of profile;

  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  update public.learner_profile as profile
  set archived_at = coalesce(profile.archived_at, now())
  where profile.id = p_learner_profile_id
  returning profile.* into v_profile;

  return v_profile;
end
$$;


--
-- Name: assemble_course_draft(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assemble_course_draft(p_course_id uuid, p_lesson_title text, p_lesson_summary text, p_components jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_assembled_at timestamptz;
  v_lesson_id uuid;
  v_component_id uuid;
  v_component jsonb;
  v_position integer := 0;
  v_lesson_ids uuid[] := '{}'::uuid[];
  v_component_ids uuid[] := '{}'::uuid[];
begin
  if p_components is null or jsonb_typeof(p_components) <> 'array' then
    raise exception
      'course_components_must_be_array'
      using errcode = '22023';
  end if;

  select course.assembled_at
  into v_assembled_at
  from public.course
  where course.id = p_course_id
  for update;

  if not found then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  if v_assembled_at is not null then
    select coalesce(
      array_agg(lesson.id order by lesson.position),
      '{}'::uuid[]
    )
    into v_lesson_ids
    from public.lesson
    where lesson.course_id = p_course_id;

    select coalesce(
      array_agg(
        component.id
        order by lesson.position, component.position
      ),
      '{}'::uuid[]
    )
    into v_component_ids
    from public.lesson_component as component
    join public.lesson on lesson.id = component.lesson_id
    where lesson.course_id = p_course_id;

    return jsonb_build_object(
      'courseId', p_course_id,
      'lessonIds', to_jsonb(v_lesson_ids),
      'componentIds', to_jsonb(v_component_ids),
      'alreadyAssembled', true
    );
  end if;

  if exists (
    select 1
    from public.lesson
    where lesson.course_id = p_course_id
  ) then
    raise exception
      'course_contains_manual_content'
      using errcode = '23505';
  end if;

  insert into public.lesson (course_id, position, title, summary)
  values (p_course_id, 1, p_lesson_title, p_lesson_summary)
  returning id into v_lesson_id;

  for v_component in
    select component.value
    from jsonb_array_elements(p_components) as component(value)
  loop
    v_position := v_position + 1;

    insert into public.lesson_component (
      lesson_id,
      position,
      type_key,
      schema_version,
      payload,
      placement_config
    )
    values (
      v_lesson_id,
      v_position,
      v_component ->> 'typeKey',
      (v_component ->> 'schemaVersion')::integer,
      v_component -> 'payload',
      v_component -> 'placement'
    )
    returning id into v_component_id;

    v_component_ids := array_append(v_component_ids, v_component_id);
  end loop;

  update public.course
  set assembled_at = now()
  where id = p_course_id;

  return jsonb_build_object(
    'courseId', p_course_id,
    'lessonIds', jsonb_build_array(v_lesson_id),
    'componentIds', to_jsonb(v_component_ids),
    'alreadyAssembled', false
  );
end
$$;


