);


--
-- Name: cancel_lesson_run(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_lesson_run(p_lesson_run_id uuid, p_cancelled_at timestamp with time zone DEFAULT now()) RETURNS public.lesson_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_lesson_id uuid;
  v_run public.lesson_run%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  if p_cancelled_at is null then
    raise exception
      'lesson_run_cancelled_at_required'
      using errcode = '22023';
  end if;

  select run.lesson_id
  into v_lesson_id
  from public.lesson_run as run
  join public.lesson as lesson on lesson.id = run.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where run.id = p_lesson_run_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = v_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  select run.*
  into v_run
  from public.lesson_run as run
  where run.id = p_lesson_run_id
    and run.lesson_id = v_lesson_id
  for update of run;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  if v_run.cancelled_at is not null then
    return v_run;
  end if;

  if v_run.ended_at is not null then
    raise exception
      'lesson_run_already_completed'
      using errcode = '55000';
  end if;

  if v_run.started_at is not null
    and p_cancelled_at < v_run.started_at
  then
    raise exception
      'lesson_run_cancelled_before_start'
      using errcode = '22007';
  end if;

  perform 1
  from public.learning_record as record
  where record.lesson_run_id = p_lesson_run_id
  order by record.id
  for update;

  if exists (
    select 1
    from public.learning_record as record
    where record.lesson_run_id = p_lesson_run_id
      and record.occurred_at is not null
  ) then
    raise exception
      'lesson_run_contains_finalized_records'
      using errcode = '55000';
  end if;

  delete from public.learning_record as record
  where record.lesson_run_id = p_lesson_run_id
    and record.occurred_at is null;

  update public.lesson_run as run
  set cancelled_at = p_cancelled_at
  where run.id = p_lesson_run_id
  returning run.* into v_run;

  return v_run;
end
$$;


--
-- Name: cleanup_empty_lesson_student_slide(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_empty_lesson_student_slide() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.student_slide_id is null
    or not exists (
      select 1 from public.lesson where lesson.id = old.lesson_id
    )
  then
    return old;
  end if;

  delete from public.lesson_student_slide as slide
  where slide.id = old.student_slide_id
    and slide.lesson_id = old.lesson_id
    and not exists (
      select 1
      from public.lesson_component as component
      where component.student_slide_id = slide.id
        and component.visibility = 'learner_visible'
    );

  if found then
    with ordered as (
      select
        slide.id,
        row_number() over (order by slide.position, slide.id)::integer
          as new_position
      from public.lesson_student_slide as slide
      where slide.lesson_id = old.lesson_id
    )
    update public.lesson_student_slide as slide
    set position = ordered.new_position
    from ordered
    where slide.id = ordered.id
      and slide.position <> ordered.new_position;
  end if;

  return old;
end
$$;


