--
-- Name: delete_learner_group(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_learner_group(p_learner_group_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_owner_account_id uuid;
begin
  if v_actor_user_id is null then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  select account.id
  into v_owner_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  join public.course_learner_group as course_group
    on course_group.course_id = course.id
  where course_group.learner_group_id = p_learner_group_id
    and course.owner_account_id = v_owner_account_id
  order by course.id
  for update of course;

  perform 1
  from public.learner_group as learner_group
  where learner_group.id = p_learner_group_id
    and learner_group.owner_account_id = v_owner_account_id
  for update of learner_group;

  if not found then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  -- Cascades remove only this collection's member and Course links. Learner
  -- profiles, LearningRecords, and frozen LessonRun drafts remain untouched.
  delete from public.learner_group as learner_group
  where learner_group.id = p_learner_group_id;

  return true;
end
$$;


--
-- Name: delete_lesson_component(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_lesson_component(p_component_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_lesson_id uuid;
  v_deleted_count integer;
begin
  if v_actor_user_id is null then
    return false;
  end if;

  select component.lesson_id
  into v_lesson_id
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where component.id = p_component_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    return false;
  end if;

  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = v_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    return false;
  end if;

  perform 1
  from public.lesson_component as component
  where component.lesson_id = v_lesson_id
  order by component.id
  for update;

  perform 1
  from public.lesson_student_slide as slide
  where slide.lesson_id = v_lesson_id
  order by slide.id
  for update;

  delete from public.lesson_component as component
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id;

  get diagnostics v_deleted_count = row_count;
  return v_deleted_count = 1;
end
$$;


--
-- Name: delete_lesson_with_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_lesson_with_history(p_lesson_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
begin
  if v_actor_user_id is null then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = p_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  -- Cascades delete Components, Slides and Runs. The Run BEFORE DELETE trigger
  -- removes drafts; finalized records retain learner data and course source,
  -- while lesson_run_id/source_lesson_id become NULL through their FKs.
  delete from public.lesson as lesson
  where lesson.id = p_lesson_id;

  return true;
end
$$;


--
-- Name: detach_archived_learner_profile_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detach_archived_learner_profile_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.archived_at is null and new.archived_at is not null then
    delete from public.course_learner as course_learner
    where course_learner.learner_profile_id = new.id;

    delete from public.learner_group_member as member
    where member.learner_profile_id = new.id;
  end if;

  return new;
end
$$;


--
-- Name: enforce_course_learner_group_same_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_course_learner_group_same_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.course as course
    join public.learner_group as learner_group
      on learner_group.id = new.learner_group_id
    where course.id = new.course_id
      and course.owner_account_id = learner_group.owner_account_id
  ) then
    raise exception
      'course_learner_group_owner_mismatch'
      using errcode = '23514';
  end if;

  return new;
end
$$;


