  );
$$;


--
-- Name: merge_user_settings(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_user_settings(p_user_id uuid, p_settings jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.ensure_user_preference(p_user_id);

  update public.user_preference
  set settings = coalesce(settings, '{}'::jsonb) || coalesce(p_settings, '{}'::jsonb),
      updated_at = now()
  where user_id = p_user_id;
end
$$;


--
-- Name: onboard_parent(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onboard_parent(p_user_id uuid, p_full_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_parent_id uuid;
begin
  insert into public.parent (user_id, full_name)
  values (p_user_id, p_full_name)
  on conflict (user_id) do update
    set full_name = coalesce(excluded.full_name, public.parent.full_name),
        updated_at = now()
  returning id into v_parent_id;

  return v_parent_id;
end
$$;


--
-- Name: onboard_teacher(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onboard_teacher(p_user_id uuid, p_full_name text DEFAULT NULL::text) RETURNS TABLE(teacher_id uuid, school_id uuid, class_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_teacher_id uuid;
  v_school_id uuid;
  v_class_id uuid;
  base_slug text;
  slug_candidate text;
  i integer;
begin
  insert into public.teacher (user_id, full_name)
  values (p_user_id, p_full_name)
  on conflict (user_id) do update
    set full_name = coalesce(excluded.full_name, public.teacher.full_name),
        updated_at = now()
  returning id into v_teacher_id;

  select st.school_id into v_school_id
  from public.school_teacher st
  where st.teacher_id = v_teacher_id
  order by case when st.role = 'owner' then 0 else 1 end, st.created_at
  limit 1;

  if v_school_id is null then
    base_slug := lower(regexp_replace(coalesce(nullif(p_full_name, ''), 'teacher') || '-' || left(v_teacher_id::text, 8), '[^a-z0-9]+', '-', 'g'));
    base_slug := trim(both '-' from base_slug);
    if base_slug = '' then
      base_slug := 'school-' || left(v_teacher_id::text, 8);
    end if;

    slug_candidate := base_slug;
    i := 1;
    while exists (select 1 from public.school s where s.slug = slug_candidate) loop
      i := i + 1;
      slug_candidate := base_slug || '-' || i::text;
    end loop;

    insert into public.school (name, slug)
    values (coalesce(nullif(p_full_name, ''), 'Преподаватель') || ' — школа', slug_candidate)
    returning id into v_school_id;

    insert into public.school_teacher (school_id, teacher_id, role)
    values (v_school_id, v_teacher_id, 'owner')
    on conflict (school_id, teacher_id) do update set role = 'owner';
  end if;

  select c.id into v_class_id
  from public."class" c
  where c.school_id = v_school_id
  order by c.created_at asc, c.id asc
  limit 1;

  if v_class_id is null then
    insert into public."class" (school_id, name)
    values (v_school_id, 'Основной класс')
    returning id into v_class_id;
  end if;

  insert into public.class_teacher (class_id, teacher_id)
  values (v_class_id, v_teacher_id)
  on conflict (class_id, teacher_id) do nothing;

  return query select v_teacher_id, v_school_id, v_class_id;
end
$$;


--
-- Name: parent_in_class(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parent_in_class(p_class_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.class_student cs
    join public.student s on s.id = cs.student_id
    where cs.class_id = p_class_id and s.parent_id = public.current_parent_id()
  );
$$;


--
-- Name: parent_in_school(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parent_in_school(p_school_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.class_student cs
    join public.student s on s.id = cs.student_id
    join public.class c on c.id = cs.class_id
    where c.school_id = p_school_id and s.parent_id = public.current_parent_id()
  );
$$;


--
-- Name: reorder_lesson_component(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_lesson_component(p_component_id uuid, p_new_position integer) RETURNS TABLE(id uuid, lesson_id uuid, type_key text, schema_version integer, "position" integer, payload jsonb, placement_config jsonb, visibility text, student_slide_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_lesson_id uuid;
  v_old_position integer;
  v_component_count integer;
  v_visibility text;
  v_student_slide_id uuid;
  v_current_slide_position integer;
  v_previous_slide_position integer;
  v_next_slide_position integer;
  v_clamped_slide_position integer;
  v_clamped_slide_id uuid;
begin
  if v_actor_user_id is null then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  if p_new_position is null or p_new_position < 1 then
    raise exception
      'component_position_out_of_range'
      using errcode = '22023';
  end if;

  select component.lesson_id
  into v_lesson_id
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where component.id = p_component_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = v_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson_component as component
  where component.lesson_id = v_lesson_id
  order by component.id
  for update;

  perform 1
  from public.lesson_student_slide as slide
  where slide.lesson_id = v_lesson_id
  order by slide.id
  for update;

  select
    component.position,
    component.visibility,
    component.student_slide_id
  into v_old_position, v_visibility, v_student_slide_id
  from public.lesson_component as component
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  select count(*)::integer
  into v_component_count
  from public.lesson_component as component
  where component.lesson_id = v_lesson_id;

  if p_new_position > v_component_count then
    raise exception
      'component_position_out_of_range'
      using errcode = '22023';
  end if;

  if p_new_position < v_old_position then
    update public.lesson_component as component
    set position = component.position + 1
    where component.lesson_id = v_lesson_id
      and component.position >= p_new_position
      and component.position < v_old_position;
  elsif p_new_position > v_old_position then
    update public.lesson_component as component
    set position = component.position - 1
    where component.lesson_id = v_lesson_id
      and component.position > v_old_position
      and component.position <= p_new_position;
  end if;

  update public.lesson_component as component
  set position = p_new_position
  where component.id = p_component_id;

  if v_visibility = 'learner_visible' then
    select slide.position
    into v_current_slide_position
    from public.lesson_student_slide as slide
    where slide.id = v_student_slide_id
      and slide.lesson_id = v_lesson_id;

    select slide.position
    into v_previous_slide_position
    from public.lesson_component as component
    join public.lesson_student_slide as slide
      on slide.id = component.student_slide_id
    where component.lesson_id = v_lesson_id
      and component.id <> p_component_id
      and component.visibility = 'learner_visible'
      and component.position < p_new_position
    order by component.position desc
    limit 1;

    select slide.position
    into v_next_slide_position
    from public.lesson_component as component
    join public.lesson_student_slide as slide
      on slide.id = component.student_slide_id
    where component.lesson_id = v_lesson_id
      and component.id <> p_component_id
      and component.visibility = 'learner_visible'
      and component.position > p_new_position
    order by component.position
    limit 1;

    v_clamped_slide_position := v_current_slide_position;

    if v_previous_slide_position is not null
      and v_clamped_slide_position < v_previous_slide_position
    then
      v_clamped_slide_position := v_previous_slide_position;
    end if;

    if v_next_slide_position is not null
      and v_clamped_slide_position > v_next_slide_position
    then
      v_clamped_slide_position := v_next_slide_position;
    end if;

    if v_clamped_slide_position <> v_current_slide_position then
      select slide.id
      into v_clamped_slide_id
      from public.lesson_student_slide as slide
      where slide.lesson_id = v_lesson_id
        and slide.position = v_clamped_slide_position;

      update public.lesson_component as component
      set student_slide_id = v_clamped_slide_id
      where component.id = p_component_id;
    end if;
  end if;

  return query
  select
    component.id,
    component.lesson_id,
    component.type_key,
    component.schema_version,
    component.position,
    component.payload,
    component.placement_config,
    component.visibility,
    component.student_slide_id,
    component.created_at,
    component.updated_at
  from public.lesson_component as component
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id;
end
$$;


--
-- Name: replace_course_audience(uuid, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_course_audience(p_course_id uuid, p_direct_learner_profile_ids uuid[] DEFAULT '{}'::uuid[], p_learner_group_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_owner_account_id uuid;
  v_direct_ids uuid[];
  v_group_ids uuid[];
  v_effective_count integer;
begin
  if v_actor_user_id is null then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  if array_position(p_direct_learner_profile_ids, null) is not null
    or array_position(p_learner_group_ids, null) is not null
    or cardinality(coalesce(p_direct_learner_profile_ids, '{}'::uuid[])) > 200
    or cardinality(coalesce(p_learner_group_ids, '{}'::uuid[])) > 200
  then
    raise exception 'course_audience_ids_invalid' using errcode = '22023';
  end if;

  select account.id
  into v_owner_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  where course.id = p_course_id
    and course.owner_account_id = v_owner_account_id
  for update of course;

  if not found then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_direct_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_direct_learner_profile_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_group_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_learner_group_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  perform 1
  from public.learner_group as learner_group
  where learner_group.id = any(v_group_ids)
    and learner_group.owner_account_id = v_owner_account_id
  order by learner_group.id
  for update of learner_group;

  if cardinality(v_group_ids) <> (
    select count(*)
    from public.learner_group as learner_group
    where learner_group.id = any(v_group_ids)
      and learner_group.owner_account_id = v_owner_account_id
  ) then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.learner_profile as profile
  where profile.id = any(v_direct_ids)
    and profile.owner_account_id = v_owner_account_id
    and profile.archived_at is null
  order by profile.id
  for update of profile;

  if cardinality(v_direct_ids) <> (
    select count(*)
    from public.learner_profile as profile
    where profile.id = any(v_direct_ids)
      and profile.owner_account_id = v_owner_account_id
      and profile.archived_at is null
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  select count(*)
  into v_effective_count
  from (
    select requested.id
    from unnest(v_direct_ids) as requested(id)
    union
    select member.learner_profile_id
    from public.learner_group_member as member
    join public.learner_profile as profile
      on profile.id = member.learner_profile_id
    where member.learner_group_id = any(v_group_ids)
      and profile.archived_at is null
  ) as effective;

  if v_effective_count > 200 then
    raise exception 'course_audience_too_large' using errcode = '22023';
  end if;

  delete from public.course_learner as course_learner
  where course_learner.course_id = p_course_id
    and not (course_learner.learner_profile_id = any(v_direct_ids));

  insert into public.course_learner (course_id, learner_profile_id)
  select p_course_id, requested.id
  from unnest(v_direct_ids) as requested(id)
  on conflict (course_id, learner_profile_id) do nothing;

  delete from public.course_learner_group as course_group
  where course_group.course_id = p_course_id
    and not (course_group.learner_group_id = any(v_group_ids));

  insert into public.course_learner_group (course_id, learner_group_id)
  select p_course_id, requested.id
  from unnest(v_group_ids) as requested(id)
  on conflict (course_id, learner_group_id) do nothing;

  return true;
end
$$;


--
-- Name: replace_course_learners(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_course_learners(p_course_id uuid, p_learner_profile_ids uuid[]) RETURNS SETOF public.learner_profile
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_group_ids uuid[];
begin
  select coalesce(
    array_agg(course_group.learner_group_id order by course_group.learner_group_id),
    '{}'::uuid[]
  )
  into v_group_ids
  from public.course_learner_group as course_group
  where course_group.course_id = p_course_id;

  perform public.replace_course_audience(
    p_course_id,
    coalesce(p_learner_profile_ids, '{}'::uuid[]),
    v_group_ids
  );

  return query
  select profile.*
  from public.learner_profile as profile
  join public.course_learner as course_learner
    on course_learner.learner_profile_id = profile.id
  where course_learner.course_id = p_course_id
    and profile.archived_at is null
  order by profile.display_name, profile.id;
end
$$;


--
-- Name: reset_pin_attempts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_pin_attempts(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.ensure_user_security(p_user_id);

  update public.user_security
  set pin_failed_attempts = 0,
      pin_locked_until = null,
      updated_at = now()
  where user_id = p_user_id;
end
$$;


--
-- Name: revoke_user_sessions(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_user_sessions(p_user_id uuid, p_cutoff timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cutoff timestamptz;
begin
  perform public.ensure_user_security(p_user_id);

  update public.user_security
  set sessions_invalid_before =
        greatest(coalesce(sessions_invalid_before, p_cutoff), p_cutoff),
      updated_at = now()
  where user_id = p_user_id
  returning sessions_invalid_before into v_cutoff;

  return v_cutoff;
end
$$;


--
-- Name: schedule_lesson_run(uuid, timestamp with time zone, integer, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_lesson_run(p_lesson_id uuid, p_scheduled_at timestamp with time zone, p_planned_duration_minutes integer DEFAULT NULL::integer, p_learner_profile_ids uuid[] DEFAULT NULL::uuid[], p_expected_lesson_run_id uuid DEFAULT NULL::uuid) RETURNS public.lesson_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_owner_account_id uuid;
  v_course_id uuid;
  v_duration_minutes integer;
  v_selected_ids uuid[];
  v_run public.lesson_run%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  if p_scheduled_at is null then
    raise exception
      'lesson_run_scheduled_at_required'
      using errcode = '22023';
  end if;

  if p_planned_duration_minutes is not null
    and p_planned_duration_minutes not between 5 and 480
  then
    raise exception
      'lesson_run_duration_invalid'
      using errcode = '22023';
  end if;

  if p_learner_profile_ids is not null
    and array_position(p_learner_profile_ids, null) is not null
  then
    raise exception
      'learner_profile_ids_must_not_contain_null'
      using errcode = '22023';
  end if;

  if cardinality(coalesce(p_learner_profile_ids, '{}'::uuid[])) > 200 then
    raise exception
      'lesson_run_audience_too_large'
      using errcode = '22023';
  end if;

  -- Resolve identity read-only, then acquire the shared audience-directory
  -- mutex before Course/Lesson locks.
  select course.owner_account_id, course.id
  into v_owner_account_id, v_course_id
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = p_lesson_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.account as account
  where account.id = v_owner_account_id
    and account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  where course.id = v_course_id
    and course.owner_account_id = v_owner_account_id
  for update of course;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  select coalesce(
    p_planned_duration_minutes,
    case
      when lesson.estimated_duration_minutes between 5 and 480
        then lesson.estimated_duration_minutes
      else null
    end,
    60
  )
  into v_duration_minutes
  from public.lesson as lesson
  where lesson.id = p_lesson_id
    and lesson.course_id = v_course_id
  for update of lesson;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  select run.*
  into v_run
  from public.lesson_run as run
  where run.lesson_id = p_lesson_id
    and run.ended_at is null
    and run.cancelled_at is null
  for update of run;

  if p_expected_lesson_run_id is not null
    and (
      v_run.id is null
      or v_run.id <> p_expected_lesson_run_id
    )
  then
    raise exception
      'lesson_run_changed'
      using errcode = '55000';
  end if;

  if v_run.id is not null and v_run.started_at is not null then
    raise exception
      'lesson_run_already_started'
      using errcode = '55000';
  end if;

  if v_run.id is not null then
    perform 1
    from public.learning_record as record
    where record.lesson_run_id = v_run.id
    order by record.id
    for update of record;

    if exists (
      select 1
      from public.learning_record as record
      where record.lesson_run_id = v_run.id
        and record.occurred_at is not null
    ) then
      raise exception
        'lesson_run_contains_finalized_records'
        using errcode = '55000';
    end if;
  end if;

  if p_learner_profile_ids is null and v_run.id is not null then
    select coalesce(
      array_agg(record.learner_profile_id order by record.learner_profile_id),
      '{}'::uuid[]
    )
    into v_selected_ids
    from public.learning_record as record
    where record.lesson_run_id = v_run.id
      and record.occurred_at is null;
  elsif p_learner_profile_ids is null then
    select coalesce(array_agg(effective.id order by effective.id), '{}'::uuid[])
    into v_selected_ids
    from (
      select course_learner.learner_profile_id as id
      from public.course_learner as course_learner
      join public.learner_profile as profile
        on profile.id = course_learner.learner_profile_id
      where course_learner.course_id = v_course_id
        and profile.archived_at is null
      union
      select member.learner_profile_id as id
      from public.course_learner_group as course_group
      join public.learner_group_member as member
        on member.learner_group_id = course_group.learner_group_id
      join public.learner_profile as profile
        on profile.id = member.learner_profile_id
      where course_group.course_id = v_course_id
        and profile.archived_at is null
    ) as effective;
  else
    select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
    into v_selected_ids
    from (
      select distinct requested_id as id
      from unnest(p_learner_profile_ids) as requested(requested_id)
    ) as requested;

    if exists (
      select 1
      from unnest(v_selected_ids) as requested(id)
      left join (
        select course_learner.learner_profile_id as id
        from public.course_learner as course_learner
        join public.learner_profile as profile
          on profile.id = course_learner.learner_profile_id
        where course_learner.course_id = v_course_id
          and profile.archived_at is null
        union
        select member.learner_profile_id as id
        from public.course_learner_group as course_group
        join public.learner_group_member as member
          on member.learner_group_id = course_group.learner_group_id
        join public.learner_profile as profile
          on profile.id = member.learner_profile_id
        where course_group.course_id = v_course_id
          and profile.archived_at is null
        union
        select record.learner_profile_id as id
        from public.learning_record as record
        where v_run.id is not null
          and record.lesson_run_id = v_run.id
          and record.occurred_at is null
      ) as allowed on allowed.id = requested.id
      where allowed.id is null
    ) then
      raise exception
        'learner_profile_not_in_course'
        using errcode = 'P0002';
    end if;
  end if;

  if cardinality(v_selected_ids) = 0 then
    raise exception
      'lesson_run_requires_expected_learner'
      using errcode = '23514';
  end if;

  if cardinality(v_selected_ids) > 200 then
    raise exception
      'lesson_run_audience_too_large'
      using errcode = '22023';
  end if;

  perform 1
  from public.learner_profile as profile
  where profile.id = any(v_selected_ids)
    and profile.owner_account_id = v_owner_account_id
  order by profile.id
  for key share of profile;

  if cardinality(v_selected_ids) <> (
    select count(*)
    from public.learner_profile as profile
    where profile.id = any(v_selected_ids)
      and profile.owner_account_id = v_owner_account_id
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  if v_run.id is not null then
    update public.lesson_run as run
    set scheduled_at = p_scheduled_at,
        planned_duration_minutes = v_duration_minutes
    where run.id = v_run.id
    returning run.* into v_run;

    delete from public.learning_record as record
    where record.lesson_run_id = v_run.id
      and record.occurred_at is null;
  else
    insert into public.lesson_run (
      lesson_id,
      scheduled_at,
      planned_duration_minutes
    )
    values (
      p_lesson_id,
      p_scheduled_at,
      v_duration_minutes
    )
    returning * into v_run;
  end if;

  insert into public.learning_record (
    learner_profile_id,
    lesson_run_id,
    source_course_id,
    source_lesson_id
  )
  select
    selected.id,
    v_run.id,
    v_course_id,
    p_lesson_id
  from unnest(v_selected_ids) as selected(id);

  return v_run;
end
$$;


--
-- Name: set_last_active_profile(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_last_active_profile(p_user_id uuid, p_profile text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.ensure_user_preference(p_user_id);

  update public.user_preference
  set last_active_profile = p_profile,
      updated_at = now()
  where user_id = p_user_id;
end
$$;


