--
-- Name: set_lesson_component_student_screen(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lesson_component_student_screen(p_component_id uuid, p_mode text, p_slide_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, lesson_id uuid, type_key text, schema_version integer, "position" integer, payload jsonb, placement_config jsonb, visibility text, student_slide_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_lesson_id uuid;
  v_component_position integer;
  v_previous_slide_position integer;
  v_next_slide_position integer;
  v_target_slide_position integer;
  v_target_slide_id uuid;
  v_insert_position integer;
begin
  if v_actor_user_id is null then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  if p_mode is null or p_mode not in ('hide', 'existing', 'new') then
    raise exception
      'student_screen_mode_invalid'
      using errcode = '22023';
  end if;

  if (p_mode = 'existing' and p_slide_id is null)
    or (p_mode <> 'existing' and p_slide_id is not null)
  then
    raise exception
      'student_screen_slide_argument_invalid'
      using errcode = '22023';
  end if;

  select component.lesson_id
  into v_lesson_id
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where component.id = p_component_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  -- Parent-row serialization gives assignment and reorder one lock order per
  -- Lesson, including when callers target different components.
  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = v_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson_component as component
  where component.lesson_id = v_lesson_id
  order by component.id
  for update;

  perform 1
  from public.lesson_student_slide as slide
  where slide.lesson_id = v_lesson_id
  order by slide.id
  for update;

  select component.position
  into v_component_position
  from public.lesson_component as component
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  if p_mode = 'hide' then
    update public.lesson_component as component
    set visibility = 'staff_only',
        student_slide_id = null
    where component.id = p_component_id;
  else
    select slide.position
    into v_previous_slide_position
    from public.lesson_component as component
    join public.lesson_student_slide as slide
      on slide.id = component.student_slide_id
    where component.lesson_id = v_lesson_id
      and component.id <> p_component_id
      and component.visibility = 'learner_visible'
      and component.position < v_component_position
    order by component.position desc
    limit 1;

    select slide.position
    into v_next_slide_position
    from public.lesson_component as component
    join public.lesson_student_slide as slide
      on slide.id = component.student_slide_id
    where component.lesson_id = v_lesson_id
      and component.id <> p_component_id
      and component.visibility = 'learner_visible'
      and component.position > v_component_position
    order by component.position
    limit 1;

    if p_mode = 'existing' then
      select slide.position
      into v_target_slide_position
      from public.lesson_student_slide as slide
      where slide.id = p_slide_id
        and slide.lesson_id = v_lesson_id;

      if not found then
        raise exception
          'student_slide_not_found'
          using errcode = 'P0002';
      end if;

      if (
        v_previous_slide_position is not null
        and v_target_slide_position < v_previous_slide_position
      ) or (
        v_next_slide_position is not null
        and v_target_slide_position > v_next_slide_position
      ) then
        raise exception
          'student_slide_target_out_of_order'
          using errcode = '23514';
      end if;

      v_target_slide_id := p_slide_id;
    else
      if v_previous_slide_position is not null
        and v_next_slide_position is not null
        and v_previous_slide_position = v_next_slide_position
      then
        raise exception
          'student_slide_cannot_split_group'
          using errcode = '23514';
      end if;

      v_insert_position := case
        when v_next_slide_position is not null
          then v_next_slide_position
        when v_previous_slide_position is not null
          then v_previous_slide_position + 1
        else 1
      end;

      update public.lesson_student_slide as slide
      set position = slide.position + 1
      where slide.lesson_id = v_lesson_id
        and slide.position >= v_insert_position;

      insert into public.lesson_student_slide as inserted_slide (
        lesson_id,
        position
      )
      values (v_lesson_id, v_insert_position)
      returning inserted_slide.id into v_target_slide_id;
    end if;

    update public.lesson_component as component
    set visibility = 'learner_visible',
        student_slide_id = v_target_slide_id
    where component.id = p_component_id;
  end if;

  return query
  select
    component.id,
    component.lesson_id,
    component.type_key,
    component.schema_version,
    component.position,
    component.payload,
    component.placement_config,
    component.visibility,
    component.student_slide_id,
    component.created_at,
    component.updated_at
  from public.lesson_component as component
  where component.id = p_component_id;
end
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: set_user_pin(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_user_pin(p_user_id uuid, p_raw_pin text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.ensure_user_security(p_user_id);

  update public.user_security
  set pin_hash = crypt(p_raw_pin, gen_salt('bf')),
      pin_failed_attempts = 0,
      pin_locked_until = null,
      pin_created_at = coalesce(pin_created_at, now()),
      pin_updated_at = now(),
      updated_at = now()
  where user_id = p_user_id;
end
$$;


--
-- Name: start_lesson_run(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_lesson_run(p_lesson_run_id uuid, p_started_at timestamp with time zone DEFAULT now()) RETURNS public.lesson_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_lesson_id uuid;
  v_run public.lesson_run%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  if p_started_at is null then
    raise exception
      'lesson_run_started_at_required'
      using errcode = '22023';
  end if;

  select run.lesson_id
  into v_lesson_id
  from public.lesson_run as run
  join public.lesson as lesson on lesson.id = run.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where run.id = p_lesson_run_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = v_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  select run.*
  into v_run
  from public.lesson_run as run
  where run.id = p_lesson_run_id
    and run.lesson_id = v_lesson_id
  for update of run;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  if v_run.cancelled_at is not null or v_run.ended_at is not null then
    raise exception
      'lesson_run_not_open'
      using errcode = '55000';
  end if;

  if v_run.started_at is null then
    update public.lesson_run as run
    set started_at = p_started_at
    where run.id = p_lesson_run_id
    returning run.* into v_run;
  end if;

  return v_run;
end
$$;


--
-- Name: sync_course_audience_type_from_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_course_audience_type_from_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_course_id uuid;
begin
  for v_course_id in
    select distinct candidate.course_id
    from (
      select case when tg_op <> 'DELETE' then new.course_id end as course_id
      union all
      select case when tg_op <> 'INSERT' then old.course_id end
    ) as candidate
    where candidate.course_id is not null
    order by candidate.course_id
  loop
    update public.course as course
    set audience_type = case
      when exists (
        select 1
        from public.course_learner as course_learner
        where course_learner.course_id = v_course_id
      ) or exists (
        select 1
        from public.course_learner_group as course_group
        where course_group.course_id = v_course_id
      ) then 'learner_profile'
      else 'none'
    end
    where course.id = v_course_id;
  end loop;

  return null;
end
$$;


--
-- Name: teaches_student(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teaches_student(p_student_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.class_student cs
    join public.class_teacher ct on ct.class_id = cs.class_id
    where cs.student_id = p_student_id and ct.teacher_id = public.current_teacher_id()
  );
$$;


--
-- Name: update_learner_group(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_learner_group(p_learner_group_id uuid, p_name text, p_learner_profile_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS public.learner_group
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_owner_account_id uuid;
  v_profile_ids uuid[];
  v_group public.learner_group%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  if p_name is null
    or btrim(p_name) = ''
    or char_length(btrim(p_name)) > 160
  then
    raise exception 'learner_group_name_invalid' using errcode = '22023';
  end if;

  if array_position(p_learner_profile_ids, null) is not null
    or cardinality(coalesce(p_learner_profile_ids, '{}'::uuid[])) > 200
  then
    raise exception 'learner_profile_ids_invalid' using errcode = '22023';
  end if;

  select account.id
  into v_owner_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  join public.course_learner_group as course_group
    on course_group.course_id = course.id
  where course_group.learner_group_id = p_learner_group_id
    and course.owner_account_id = v_owner_account_id
  order by course.id
  for update of course;

  select learner_group.*
  into v_group
  from public.learner_group as learner_group
  where learner_group.id = p_learner_group_id
    and learner_group.owner_account_id = v_owner_account_id
  for update of learner_group;

  if not found then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.learner_group as learner_group
    where learner_group.owner_account_id = v_owner_account_id
      and learner_group.id <> p_learner_group_id
      and lower(btrim(learner_group.name)) = lower(btrim(p_name))
  ) then
    raise exception 'learner_group_name_taken' using errcode = '23505';
  end if;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_profile_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_learner_profile_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  perform 1
  from public.learner_profile as profile
  where profile.id = any(v_profile_ids)
    and profile.owner_account_id = v_owner_account_id
    and profile.archived_at is null
  order by profile.id
  for update of profile;

  if cardinality(v_profile_ids) <> (
    select count(*)
    from public.learner_profile as profile
    where profile.id = any(v_profile_ids)
      and profile.owner_account_id = v_owner_account_id
      and profile.archived_at is null
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  -- A Course cannot be left with an effective audience larger than the same
  -- 200-person LessonRun cap.
  if exists (
    select 1
    from public.course_learner_group as target_link
    where target_link.learner_group_id = p_learner_group_id
      and (
        select count(*)
        from (
          select course_learner.learner_profile_id
          from public.course_learner as course_learner
          join public.learner_profile as profile
            on profile.id = course_learner.learner_profile_id
          where course_learner.course_id = target_link.course_id
            and profile.archived_at is null
          union
          select member.learner_profile_id
          from public.course_learner_group as course_group
          join public.learner_group_member as member
            on member.learner_group_id = course_group.learner_group_id
          join public.learner_profile as profile
            on profile.id = member.learner_profile_id
          where course_group.course_id = target_link.course_id
            and course_group.learner_group_id <> p_learner_group_id
            and profile.archived_at is null
          union
          select requested.id
          from unnest(v_profile_ids) as requested(id)
        ) as effective
      ) > 200
  ) then
    raise exception 'course_audience_too_large' using errcode = '22023';
  end if;

  update public.learner_group as learner_group
  set name = btrim(p_name)
  where learner_group.id = p_learner_group_id
  returning learner_group.* into v_group;

  delete from public.learner_group_member as member
  where member.learner_group_id = p_learner_group_id
    and not (member.learner_profile_id = any(v_profile_ids));

  insert into public.learner_group_member (
    learner_group_id,
    learner_profile_id
  )
  select p_learner_group_id, requested.id
  from unnest(v_profile_ids) as requested(id)
  on conflict (learner_group_id, learner_profile_id) do nothing;

  return v_group;
end
$$;


--
-- Name: update_learner_profile_with_groups(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_learner_profile_with_groups(p_learner_profile_id uuid, p_display_name text, p_learner_group_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS public.learner_profile
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_owner_account_id uuid;
  v_group_ids uuid[];
  v_profile public.learner_profile%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  if p_display_name is null
    or btrim(p_display_name) = ''
    or char_length(btrim(p_display_name)) > 160
  then
    raise exception 'learner_profile_name_invalid' using errcode = '22023';
  end if;

  if array_position(p_learner_group_ids, null) is not null
    or cardinality(coalesce(p_learner_group_ids, '{}'::uuid[])) > 200
  then
    raise exception 'learner_group_ids_invalid' using errcode = '22023';
  end if;

  select account.id
  into v_owner_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  if not exists (
    select 1
    from public.learner_profile as profile
    where profile.id = p_learner_profile_id
      and profile.owner_account_id = v_owner_account_id
      and profile.archived_at is null
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_group_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_learner_group_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  if cardinality(v_group_ids) <> (
    select count(*)
    from public.learner_group as learner_group
    where learner_group.id = any(v_group_ids)
      and learner_group.owner_account_id = v_owner_account_id
  ) then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  join public.course_learner_group as course_group
    on course_group.course_id = course.id
  where course_group.learner_group_id = any(v_group_ids)
    and course.owner_account_id = v_owner_account_id
  order by course.id
  for update of course;

  -- Adding an already-effective learner through another Group does not grow
  -- the distinct Course audience. Only genuinely new effective membership is
  -- constrained by the 200-person Run cap.
  if exists (
    select 1
    from (
      select distinct course_group.course_id
      from public.course_learner_group as course_group
      where course_group.learner_group_id = any(v_group_ids)
    ) as target_course
    where not exists (
      select 1
      from (
        select course_learner.learner_profile_id
        from public.course_learner as course_learner
        join public.learner_profile as profile
          on profile.id = course_learner.learner_profile_id
        where course_learner.course_id = target_course.course_id
          and profile.archived_at is null
        union
        select member.learner_profile_id
        from public.course_learner_group as linked_group
        join public.learner_group_member as member
          on member.learner_group_id = linked_group.learner_group_id
        join public.learner_profile as profile
          on profile.id = member.learner_profile_id
        where linked_group.course_id = target_course.course_id
          and profile.archived_at is null
      ) as current_effective
      where current_effective.learner_profile_id = p_learner_profile_id
    )
      and (
        select count(*)
        from (
          select course_learner.learner_profile_id
          from public.course_learner as course_learner
          join public.learner_profile as profile
            on profile.id = course_learner.learner_profile_id
          where course_learner.course_id = target_course.course_id
            and profile.archived_at is null
          union
          select member.learner_profile_id
          from public.course_learner_group as linked_group
          join public.learner_group_member as member
            on member.learner_group_id = linked_group.learner_group_id
          join public.learner_profile as profile
            on profile.id = member.learner_profile_id
          where linked_group.course_id = target_course.course_id
            and profile.archived_at is null
        ) as effective
      ) >= 200
  ) then
    raise exception 'course_audience_too_large' using errcode = '22023';
  end if;

  perform 1
  from public.learner_group as learner_group
  where learner_group.id = any(v_group_ids)
    and learner_group.owner_account_id = v_owner_account_id
  order by learner_group.id
  for update of learner_group;

  select profile.*
  into v_profile
  from public.learner_profile as profile
  where profile.id = p_learner_profile_id
    and profile.owner_account_id = v_owner_account_id
    and profile.archived_at is null
  for update of profile;

  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  update public.learner_profile as profile
  set display_name = btrim(p_display_name)
  where profile.id = p_learner_profile_id
  returning profile.* into v_profile;

  delete from public.learner_group_member as member
  where member.learner_profile_id = p_learner_profile_id
    and not (member.learner_group_id = any(v_group_ids));

  insert into public.learner_group_member (
    learner_group_id,
    learner_profile_id
  )
  select requested.id, p_learner_profile_id
  from unnest(v_group_ids) as requested(id)
  on conflict (learner_group_id, learner_profile_id) do nothing;

  return v_profile;
end
$$;


--
-- Name: upsert_user_theme(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_user_theme(p_user_id uuid, p_theme text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.ensure_user_preference(p_user_id);

  update public.user_preference
  set theme = p_theme,
      updated_at = now()
  where user_id = p_user_id;
end
$$;


--
-- Name: verify_user_pin(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_user_pin(p_user_id uuid, p_raw_pin text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sec public.user_security;
  v_ok boolean := false;
  v_max_attempts constant integer := 5;
  v_lock_minutes constant integer := 15;
begin
  select * into v_sec from public.ensure_user_security(p_user_id);

  if v_sec.pin_hash is null then
    return false;
  end if;

  if v_sec.pin_locked_until is not null and v_sec.pin_locked_until > now() then
    return false;
  end if;

  v_ok := crypt(p_raw_pin, v_sec.pin_hash) = v_sec.pin_hash;

  if v_ok then
    update public.user_security
    set pin_failed_attempts = 0,
        pin_locked_until = null,
        last_pin_login_at = now(),
        updated_at = now()
    where user_id = p_user_id;
    return true;
  end if;

  update public.user_security
  set pin_failed_attempts = pin_failed_attempts + 1,
      pin_locked_until = case
        when pin_failed_attempts + 1 >= v_max_attempts then now() + make_interval(mins => v_lock_minutes)
        else null
      end,
      updated_at = now()
  where user_id = p_user_id;

  return false;
end
$$;


